sql.where:
L.STATUS != 'DELETED'
AND L.STATUS != 'HIDDEN'
AND ( LOWER(L.TITLE) LIKE '%' || LOWER(#{keyword}) || '%' OR LOWER(L.ITEM_NAME) LIKE '%' || LOWER(#{keyword}) || '%' OR LOWER(L.COLOR) LIKE '%' || LOWER(#{keyword}) || '%' OR LOWER(L.BRAND) LIKE '%' || LOWER(#{keyword}) || '%' OR LOWER(C.CATEGORY_NAME) LIKE '%' || LOWER(#{keyword}) || '%' OR DBMS_LOB.INSTR(L.DESCRIPTION, #{keyword}) > 0 OR LOWER(LOC.LOCATION_NAME) LIKE '%' || LOWER(#{keyword}) || '%' OR LOWER(L.LOST_LOCATION_DETAIL) LIKE '%' || LOWER(#{keyword}) || '%' )
AND L.CATEGORY_ID = #{categoryId,jdbcType=NUMERIC}
AND L.LOST_LOCATION_ID = #{locationId}
AND LOC.LOCATION_NAME LIKE '%' || #{locationName} || '%'
AND L.STATUS = #{status,jdbcType=VARCHAR}

F.STATUS != 'DELETED'
AND F.STATUS != 'HIDDEN'
AND ( LOWER(F.TITLE) LIKE '%' || LOWER(#{keyword}) || '%' OR LOWER(F.ITEM_NAME) LIKE '%' || LOWER(#{keyword}) || '%' OR LOWER(F.COLOR) LIKE '%' || LOWER(#{keyword}) || '%' OR LOWER(F.BRAND) LIKE '%' || LOWER(#{keyword}) || '%' OR LOWER(C.CATEGORY_NAME) LIKE '%' || LOWER(#{keyword}) || '%' OR DBMS_LOB.INSTR(F.DESCRIPTION, #{keyword}) > 0 OR LOWER(LOC.LOCATION_NAME) LIKE '%' || LOWER(#{keyword}) || '%' OR LOWER(F.FOUND_LOCATION_DETAIL) LIKE '%' || LOWER(#{keyword}) || '%' )
AND F.CATEGORY_ID = #{categoryId,jdbcType=NUMERIC}
AND F.FOUND_LOCATION_ID = #{locationId}
AND LOC.LOCATION_NAME LIKE '%' || #{locationName} || '%'
AND F.STATUS IN ('STORED', 'REGISTERED')
AND F.STATUS = #{status,jdbcType=VARCHAR}

mapper.insert:

    SELECT SEQ_REPORTS.NEXTVAL FROM DUAL

INSERT INTO REPORTS (
    REPORT_ID, REPORTER_ID, TARGET_TYPE, TARGET_ID, REASON, DETAIL, STATUS, CREATED_AT
) VALUES (
    #{reportId}, #{reporterId,jdbcType=NUMERIC}, #{targetType,jdbcType=VARCHAR}, #{targetId,jdbcType=NUMERIC}, #{reasonType,jdbcType=VARCHAR}, #{reasonDetail,jdbcType=VARCHAR}, #{status,jdbcType=VARCHAR}, SYSDATE
)

mapper.select:
SELECT * FROM ( SELECT L.LOST_ID AS ID, L.USER_ID, 'lost' AS ITEM_TYPE, L.TITLE, L.CATEGORY_ID, C.CATEGORY_NAME, L.ITEM_NAME, L.COLOR, L.BRAND, L.LOST_LOCATION_ID AS LOCATION_ID, LOC.LOCATION_NAME, L.LOST_LOCATION_DETAIL AS LOCATION_DETAIL, L.LOST_DATE AS ITEM_DATE, L.LOST_TIME AS ITEM_TIME, L.LOST_TIME_RANGE AS ITEM_TIME_RANGE, NULL AS STORAGE_ID, NULL AS STORAGE_NAME, DBMS_LOB.SUBSTR(L.DESCRIPTION, 1000, 1) AS DESCRIPTION, L.STATUS, L.VIEW_COUNT, L.CREATED_AT, U.USER_NAME AS WRITER_NAME, U.STUDENT_NO, NULL AS SCHOOL, IMG.IMAGE_URL FROM LOST_ITEMS L JOIN USERS U ON U.USER_ID = L.USER_ID LEFT JOIN CATEGORIES C ON C.CATEGORY_ID = L.CATEGORY_ID LEFT JOIN LOCATIONS LOC ON LOC.LOCATION_ID = L.LOST_LOCATION_ID LEFT JOIN ( SELECT ITEM_ID, MIN(IMAGE_URL) KEEP (DENSE_RANK FIRST ORDER BY NVL(SORT_ORDER, 9999), IMAGE_ID) AS IMAGE_URL FROM ITEM_IMAGES WHERE ITEM_TYPE = 'lost' GROUP BY ITEM_ID ) IMG ON IMG.ITEM_ID = L.LOST_ID
ORDER BY L.CREATED_AT ASC ORDER BY L.VIEW_COUNT DESC, L.CREATED_AT DESC ORDER BY L.CREATED_AT DESC
) WHERE ROWNUM <= 100

mapper.update:
UPDATE LOST_ITEMS
SET VIEW_COUNT = VIEW_COUNT + 1
WHERE LOST_ID = #{lostId,jdbcType=NUMERIC}

mapper.select:
SELECT * FROM ( SELECT F.FOUND_ID AS ID, F.USER_ID, 'found' AS ITEM_TYPE, F.TITLE, F.CATEGORY_ID, C.CATEGORY_NAME, F.ITEM_NAME, F.COLOR, F.BRAND, F.FOUND_LOCATION_ID AS LOCATION_ID, LOC.LOCATION_NAME, F.FOUND_LOCATION_DETAIL AS LOCATION_DETAIL, F.FOUND_DATE AS ITEM_DATE, F.FOUND_TIME AS ITEM_TIME, F.FOUND_TIME_RANGE AS ITEM_TIME_RANGE, F.STORAGE_ID, SP.STORAGE_NAME, DBMS_LOB.SUBSTR(F.DESCRIPTION, 1000, 1) AS DESCRIPTION, F.STATUS, F.VIEW_COUNT, F.CREATED_AT, U.USER_NAME AS WRITER_NAME, U.STUDENT_NO, NULL AS SCHOOL, IMG.IMAGE_URL FROM FOUND_ITEMS F JOIN USERS U ON U.USER_ID = F.USER_ID LEFT JOIN CATEGORIES C ON C.CATEGORY_ID = F.CATEGORY_ID LEFT JOIN LOCATIONS LOC ON LOC.LOCATION_ID = F.FOUND_LOCATION_ID LEFT JOIN STORAGE_PLACES SP ON SP.STORAGE_ID = F.STORAGE_ID LEFT JOIN LOCATIONS SL ON SL.LOCATION_ID = SP.LOCATION_ID LEFT JOIN ( SELECT ITEM_ID, MIN(IMAGE_URL) KEEP (DENSE_RANK FIRST ORDER BY NVL(SORT_ORDER, 9999), IMAGE_ID) AS IMAGE_URL FROM ITEM_IMAGES WHERE ITEM_TYPE = 'found' GROUP BY ITEM_ID ) IMG ON IMG.ITEM_ID = F.FOUND_ID
ORDER BY F.CREATED_AT ASC ORDER BY F.VIEW_COUNT DESC, F.CREATED_AT DESC ORDER BY F.CREATED_AT DESC
) WHERE ROWNUM <= 100

mapper.update:
UPDATE FOUND_ITEMS
SET VIEW_COUNT = VIEW_COUNT + 1
WHERE FOUND_ID = #{foundId,jdbcType=NUMERIC}

mapper.insert:

    SELECT SEQ_ITEM_IMAGES.NEXTVAL FROM DUAL

INSERT INTO ITEM_IMAGES (
    IMAGE_ID, ITEM_TYPE, ITEM_ID, IMAGE_URL, ORIGINAL_NAME, SAVED_NAME, SORT_ORDER, CREATED_AT
) VALUES (
    #{imageId}, #{itemType}, #{itemId}, #{imageUrl}, #{originalName}, #{savedName}, #{sortOrder}, SYSDATE
)

mapper.select:
SELECT COUNT(*) FROM REPORTS R
AND ( R.REASON LIKE '%' || #{keyword} || '%' OR DBMS_LOB.INSTR(R.DETAIL, #{keyword}) > 0 OR ('FALSE_INFO' = R.REASON AND '허위 게시글' LIKE '%' || #{keyword} || '%') OR ('PRIVATE_INFO' = R.REASON AND '개인정보 노출' LIKE '%' || #{keyword} || '%') OR ('DUPLICATE' = R.REASON AND '중복 게시글' LIKE '%' || #{keyword} || '%') OR ('BAD_CONTENT' = R.REASON AND '부적절한 내용' LIKE '%' || #{keyword} || '%') OR ('SPAM' = R.REASON AND '광고/스팸' LIKE '%' || #{keyword} || '%') OR ('ETC' = R.REASON AND '기타' LIKE '%' || #{keyword} || '%') )
AND R.STATUS = #{status,jdbcType=VARCHAR}

mapper.update:
UPDATE REPORTS
SET STATUS = #{status,jdbcType=VARCHAR}, PROCESSED_AT = SYSDATE
WHERE REPORT_ID = #{reportId}

UPDATE LOST_ITEMS
SET STATUS = #{status,jdbcType=VARCHAR}, UPDATED_AT = SYSDATE
WHERE LOST_ID = #{lostId,jdbcType=NUMERIC}

UPDATE FOUND_ITEMS
SET STATUS = #{status,jdbcType=VARCHAR}, UPDATED_AT = SYSDATE
WHERE FOUND_ID = #{foundId,jdbcType=NUMERIC}

UPDATE LOST_ITEMS
SET STATUS = 'DELETED',
    UPDATED_AT = SYSDATE
WHERE LOST_ID = #{lostId,jdbcType=NUMERIC}
  AND USER_ID = #{userId,jdbcType=NUMERIC}
  AND STATUS != 'DELETED'

mapper.select:
SELECT COUNT(*)
FROM LOST_ITEMS
WHERE LOST_ID = #{lostId,jdbcType=NUMERIC}
  AND USER_ID = #{userId,jdbcType=NUMERIC}
  AND STATUS != 'DELETED'

mapper.update:
