SET STATUS = 'DELETED',
    UPDATED_AT = SYSDATE
WHERE FOUND_ID = #{foundId,jdbcType=NUMERIC}
  AND USER_ID = #{userId,jdbcType=NUMERIC}
  AND STATUS != 'DELETED'

mapper.select:
SELECT COUNT(*)
FROM FOUND_ITEMS
WHERE FOUND_ID = #{foundId,jdbcType=NUMERIC}
  AND USER_ID = #{userId,jdbcType=NUMERIC}
  AND STATUS != 'DELETED'

mapper.delete:
DELETE FROM ITEM_IMAGES
WHERE ITEM_TYPE = #{itemType}
  AND ITEM_ID = #{itemId}
